			intro_p2: "為了回答這個問題,本次審計生成了 1,010,000 張電腦模擬、數學上中立的阿爾伯塔地圖。模擬使用了委員會地理範圍上的 Elections Alberta 官方 shapefile,將每一份方案都置於相同的人口均衡(±25%)與連續性要求之下——這是演算法所強制執行的兩項標準,而非每一項法定因素(例如它並不強制執行利益共同體),因此這套比較地圖集最好理解為人口與連續性中立,而非完全符合法定規定。然後將委員會的兩份 2026 年地圖放入該分布,以查看它們有多麼正常。模擬執行了四條獨立的鏈,每條 252,500 步,基礎種子來自 Cloudflare drand 信標,並在執行前於 OSF 預先註冊。",
