			p2: "在這裡,翻譯品質的重要性是大多數網站所沒有的。本次審計就選舉公平性提出統計性主張,一個譯錯的數字或一句限定語氣不當的句子,會以讀者難以察覺的方式造成誤導。對公民統計類文字做機器翻譯確實很難。出錯的可能性很大。",
