			c5_cond: "背景:2026 年 4 月 22 日——即阿爾伯塔通過政府第 37 號議案的次日——加拿大最高法院以 7 比 2、當庭維持魁北克上訴法院的裁決,即 Legault 政府對其選區重劃委員會的立法凍結違反了《憲章》第 3 條的民主代表保障。條件:審查阿爾伯塔議案的法院發現它在憲法上有別——例如,因為將工作重新指派給 MLA 委員會在結構上不同於立法凍結,或因為阿爾伯塔的有效代表權分析在第 3 條下的結果與魁北克不同。",
