			corr_municipal: "<strong>市政錨定。</strong>使用臨時地圖邊界的早期草稿分析顯示,少數派地圖只有 15% 的時間錨定在市政界線上——比 70–85% 的加拿大常態低 4.9&times;。這個數字是臨時(DPG 時期)邊界重建造成的假象。在 Elections Alberta 官方標準 shapefile 上,兩份地圖的錨定都在加拿大常態範圍內:多數派 80%,少數派 72%。兩份地圖在市政錨定上的<em>差異</em>,不是一個經得起標準重算的訊號。委員會主席標記的三處邊界異常(Rocky Mountain House–Banff Park、Nolan Hill–Cochrane、Olds–North Airdrie)仍然存在,不受這項更正影響。"
