				li1: "<strong>1. 人口分佈。</strong>選區偏離理想人口有多遠?按委員會自己的表格,多數派地圖的選區平均偏離 3,180 人。少數派地圖的偏離 4,707 人,大約多一半。偏離越大,選票的分量就越不平等。不過,按 2021 年人口普查數字,三張地圖的平均偏離幾乎相同。",
				li2: "<strong>2. Calgary 的擠迫。</strong>在 Calgary 東北部和中部,少數派地圖的選區人口比全省平均多 11.5%。多數派地圖的多 2.8%。(如果按字面解讀這個區域所述的地理規則,數字是 8.5% 至 8.9%,以及 1.3% 至 1.6%。)在較大的選區中,每一票的分量較輕。把一個政黨的選民擠進較少、較大的選區,叫做<em>集中</em>。但我的集中檢驗在這裡沒有偵測到它:按 2023 年的選票,NDP 贏下這個區域十七個選區中的八個,勝幅都低於全省平均。",
				li3: "<strong>3. Airdrie 的分割。</strong>法律要求 Airdrie 至少有兩個選區。多數派地圖用了兩個。少數派地圖把這座城市切成四塊(其中三塊擁有其至少 2% 的人口),每一塊都與城市以外的不同土地合併。把一個社區分得很薄,叫做<em>分散</em>。這種分割越過了這項檢驗的線。它沒有越過我另外那項探索性的分散檢驗:Airdrie East 把超過半個城市保持在一起,而它的人口十個中有九個住在 Airdrie。",
				li4: "<strong>4. 主席的標記。</strong>委員會多數派(包括主席在內)在報告中把一些邊界標示為在地理上很奇怪。它的標記中有四項落在少數派地圖上,我自己的幾何核對確認了三項。沒有一項落在多數派地圖上。",
				li5: "<strong>5. 沿著城市和城鎮界線。</strong>兩張地圖沿著這些界線的頻率都與 2019 年地圖差不多,即 75%(多數派 80%,少數派 72%)。所以這項檢驗無法區分兩張地圖。它失敗了,但它留在這一頁上。",
