				li1: "<strong>1. 50-50 檢驗。</strong>把每個選區的選票都移動同樣的幅度,直到全省剛好 50-50 平分,然後數每個政黨的議席。在阿爾伯塔,一張典型的電腦繪製地圖在平票時給 UCP 44.8% 的議席,因為 UCP 在鄉村的勝幅比 NDP 在城市的勝幅更大。多數派地圖給 UCP 46.1%:第 78 百分位,很普通。2019 年地圖給 46.0%:第 65 百分位(或按最初登記的方式,如果把每一張與它持平的地圖都計在它之下,則是第 78 百分位)。少數派地圖給 UCP <strong>51.7%</strong>(89 席中的 46 席),即在平票時取得過半議席。1,010,000 張電腦繪製的地圖中只有 69 張給 UCP 更多。作為參照,一種被指示<em>刻意</em>為 UCP 贏得盡可能多議席的方法,在一次設定種子的運行中達到 52.9%(87 席中的 46 席)。沒有任何東西顯示這已經是最大的可能。",
				li2: "<strong>2. 效率差距。</strong>每一票要麼幫助贏得一個議席,要麼是「浪費」的:投給了落敗者,或者在勝者超出勝出所需之後仍堆在它身上。這項指標比較兩個政黨浪費的選票。正的差距有利於 UCP。多數派地圖得分 +0.1%,接近零。少數派地圖得分 +4.0%,即第 94.5 百分位。這剛好<em>低於</em>我事先定下的線,即第 95 百分位(約 +4.1%)。這是唯一一項沒有標記的指標,我把它報告為未達標。",
				li3: "<strong>3. 平均數-中位數差距。</strong>把一個政黨的選區平均結果與它居中的選區結果作比較。當兩者相差越來越遠,就表示選票在某處被聚集成大勝。少數派地圖的差距比 99.97% 的電腦繪製地圖更有利於 UCP。多數派地圖的差距偏向另一方向,即偏向 NDP,比 99% 的電腦繪製地圖偏得更遠。我也報告這個異常值。我沒有經過檢驗的解釋。",
				li4: "<strong>4. Declination(偏斜度)。</strong>它解讀勝出差距:地圖是否同樣對待兩個政黨的勝利,還是在 50% 這一點上彎折?少數派地圖向 UCP 有利方向的彎折,比 98.8% 的電腦繪製地圖更大。多數派地圖的讀數正常。",
