				p2: "我在兩個地方尋找訊號:這個合併分數,以及另一項關於具體邊界選擇的檢驗。在兩個地方尋找,就給了運氣兩次機會。想想彩票:買兩張,你中獎的機率就加倍。所以在引用機率之前,我先對自己不利地把它加倍。這樣「你試了兩次」就已經被計算在內。第二項檢驗後來撤下了,所以加倍保留作一個審慎的寬限,而不是針對一組已說明之檢驗的校正。",
