				li1: "<strong>更換引擎。</strong>我用另一種繪製地圖的方式重新運行四項公平性指標:一種生成森林抽樣器,事先在 OSF 登記(he53s),並於 2026 年 7 月 10 日運行。每一個百分位的移動都不到一個百分點。這符合我為把結果稱為穩健而定下的規則。但這次運行遠遠未達到它的計劃規模,而它的誤差範圍約為兩個百分點。所以我把它解讀為在這個運行規模下無法定論,而不是穩健的發現。它顯示的是地圖仍然偏得很遠,而不是確切有多遠。在這個引擎上,合併機率約為 20,000 分之 1。",
