				li1: "<strong>委員會在它唯一的工作上失敗了。</strong>委員會應該在保持距離的情況下給出一個答案。這一屆給了兩張無法同時使用的地圖,而它的多數派公開指控少數派惡意行事。當獨立的途徑分裂時,總得有人作決定。法律說明了由誰來決定。",
				li2: "<strong>法律刻意把筆交給立法機構。</strong>根據阿爾伯塔的法律,委員會的報告沒有法律效力。只有在議會通過一部《<em>Electoral Divisions Act</em>》時,選區才會改變。第 37 號議案使用的是法律刻意建造的一道門。沒有任何東西是偷偷塞進來的。",
				li3: "<strong>MLA 要向選民負責;委員不向任何人負責。</strong>讓立法機構控制地圖的最古老論點是問責。一位繪製自利地圖的 MLA 可以被選下台。一位委員則不能。",
				li4: "<strong>特別委員會並非純粹出於黨派。</strong>它的六位成員中有兩位是 NDP 的 MLA。地圖由一個諮詢小組繪製。這個小組包括兩名由反對黨提名的成員,並由一位退休上訴法院法官擔任主席。它也分裂了:它的報告包括一份少數意見。",
