				p2: "看這份評分表的另一種方式:它加上了第三個維度。本審計的圖表把每張地圖放在兩個維度上:它的界線如何劃定,以及它如何把選票轉化為議席。到目前為止,圖表上的三張地圖(委員會的多數派和少數派地圖,以及 2019 年地圖)全都來自委員會程序,而它們在這裡按設計都得到九項中九項。所以第三個維度一直沒有什麼可以區分。小組的地圖是本審計中第一張背後有不同程序得分的地圖。",
				p3: "請公平地、從兩個方向閱讀這個表格。委員會得到九項中九項是<em>按設計</em>的。這些保障描述的是規範所建立的機構,而委員會就是那個機構。能說明問題的部分取決於特別委員會。它的「否」中有四項,是它在提交報告之前本可以加上的保障:聽證、公佈草案、新的意見,以及這些所帶來的對公眾的回應。它一項都沒有加上。它在 10 月 28 日結束審查,此後沒有再開會。",
