				p1: "本審計的每一個版本都遵循同一條規則。它可以報告檢驗所顯示的。它可以說明一張地圖與電腦沒有目的地繪製的地圖相比有多不尋常。它不稱任何地圖為 gerrymander。它不從界線的形狀猜測意圖。而且它不就一張地圖是否符合憲法或該法作出裁定。這些問題屬於法院、委員會和讀者,由他們面對本審計的證據來判斷。",
